package com.az.scicalc;
import android.app.Dialog;
import android.graphics.Color;
import android.graphics.drawable.ColorDrawable;
import android.view.*;
import android.widget.*;

/** Decimal format chooser with a live sample and per-format precision. */
final class FormatSheet {
 static void show(MainActivity app){Dialog dialog=new Dialog(app);ToolPage units=new ToolPage(app,"",()->{});LinearLayout content=new LinearLayout(app);content.setOrientation(1);content.setBackground(ToolPage.rounded(app,0xff343339,30));content.setClipToOutline(true);
  LinearLayout header=new LinearLayout(app);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(units.dp(16),0,units.dp(8),0);TextView title=ToolPage.text(app,"小数显示格式",18);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));header.addView(ToolPage.icon(app,"close","关闭小数格式",dialog::dismiss,.6f),new LinearLayout.LayoutParams(units.dp(40),-1));content.addView(header,new LinearLayout.LayoutParams(-1,units.dp(60)));
  ScrollView scroll=new ScrollView(app);LinearLayout body=new LinearLayout(app);body.setOrientation(1);scroll.addView(body);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));String[] styles={"normal","fixed","scientific","engineering","si"},labels={"正常模式","固定模式","科学模式","工程模式","工程 SI 模式"},abbreviations={"NORM","FIX","SCI","ENG","ENG(SI)"};Runnable[] render=new Runnable[1];render[0]=()->{body.removeAllViews();
   LinearLayout settings=new LinearLayout(app);settings.setGravity(Gravity.CENTER_VERTICAL);settings.setPadding(units.dp(14),units.dp(12),units.dp(14),units.dp(12));settings.addView(ToolPage.icon(app,"gear","格式与分隔符设置",()->{dialog.dismiss();app.menuTools.settingsFormat();},.7f),new LinearLayout.LayoutParams(units.dp(36),units.dp(40)));TextView link=ToolPage.text(app,"设置 / 分隔符号\n1234567890 → 1,234,567,890",17);settings.addView(link,new LinearLayout.LayoutParams(0,-2,1));settings.setOnClickListener(v->{dialog.dismiss();app.menuTools.settingsFormat();});body.addView(settings);divider(body,units);
   String selected=app.prefs.getString("numberFormat","normal");int digits=app.prefs.getInt("digits",11);
   for(int i=0;i<styles.length;i++){final String style=styles[i];LinearLayout row=new LinearLayout(app);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(units.dp(12),0,units.dp(16),0);RadioButton radio=new RadioButton(app);radio.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{ToolPage.ACCENT,ToolPage.TEXT}));radio.setChecked(style.equals(selected));row.addView(radio,new LinearLayout.LayoutParams(units.dp(36),units.dp(52)));TextView label=ToolPage.text(app,labels[i],18);row.addView(label,new LinearLayout.LayoutParams(0,-1,1));TextView abbr=ToolPage.text(app,abbreviations[i],17);abbr.setTypeface(UiFonts.MONO);row.addView(abbr);Runnable choose=()->{app.prefs.edit().putString("numberFormat",style).apply();app.refreshResult();app.applyPreferences();render[0].run();};radio.setOnClickListener(v->choose.run());row.setOnClickListener(v->choose.run());body.addView(row,new LinearLayout.LayoutParams(-1,units.dp(52)));
    String value=ResultFormat.scientific(ResultFormat.format("31415.92653589793",style,digits),app.prefs.getBoolean("scientificE",false));FormulaPreview sample=new FormulaPreview(app,"",value,false,ToolPage.TEXT,18);body.addView(sample,new LinearLayout.LayoutParams(-1,-2));
    if(style.equals(selected)){LinearLayout caption=new LinearLayout(app);caption.setPadding(units.dp(16),0,units.dp(16),0);TextView decimal=ToolPage.text(app,style.equals("fixed")?"小数位数":"有效位数",17);caption.addView(decimal,new LinearLayout.LayoutParams(0,-2,1));TextView number=ToolPage.text(app,""+digits,17);caption.addView(number);body.addView(caption);LinearLayout controls=new LinearLayout(app);controls.setGravity(Gravity.CENTER_VERTICAL);controls.setPadding(units.dp(16),0,units.dp(16),units.dp(16));SeekBar seek=new SeekBar(app);seek.setMax(13);seek.setProgress(digits-2);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff53545e));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(ToolPage.TEXT));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int n,boolean user){if(user){app.prefs.edit().putInt("digits",n+2).apply();number.setText(""+(n+2));}}public void onStopTrackingTouch(SeekBar s){app.refreshResult();app.applyPreferences();render[0].run();}});TextView minus=ToolPage.text(app,"−",22),plus=ToolPage.text(app,"+",22);minus.setGravity(Gravity.CENTER);plus.setGravity(Gravity.CENTER);minus.setOnClickListener(v->{app.prefs.edit().putInt("digits",Math.max(2,digits-1)).apply();app.refreshResult();app.applyPreferences();render[0].run();});plus.setOnClickListener(v->{app.prefs.edit().putInt("digits",Math.min(15,digits+1)).apply();app.refreshResult();app.applyPreferences();render[0].run();});controls.addView(minus,new LinearLayout.LayoutParams(units.dp(40),units.dp(44)));controls.addView(seek,new LinearLayout.LayoutParams(0,units.dp(44),1));controls.addView(plus,new LinearLayout.LayoutParams(units.dp(40),units.dp(44)));body.addView(controls);}
    divider(body,units);
   }
  };render[0].run();dialog.setContentView(content);dialog.show();Window window=dialog.getWindow();window.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));window.setGravity(Gravity.BOTTOM);window.setLayout(-1,Math.round(app.getResources().getDisplayMetrics().heightPixels*.78f));window.setDimAmount(.35f);
 }
 static void divider(LinearLayout body,ToolPage units){View line=new View(body.getContext());line.setBackgroundColor(0xff48474e);body.addView(line,new LinearLayout.LayoutParams(-1,units.dp(.6f)));}
}
